-- triggers INSERT/UPDATE/DELETE en toda tabla de negocio que no los tenía.
DELIMITER //
ALTER TABLE LOG_AUDITORIA ADD COLUMN log_Seq BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, ADD UNIQUE KEY UQ_LOG_SEQ (log_Seq)//
ALTER TABLE LOG_AUDITORIA ADD COLUMN log_Sede VARCHAR(20) NOT NULL DEFAULT '<SEDE>'//
DROP TRIGGER IF EXISTS TRG_AUD_DWH_DIM_CLIENTE_AI//
CREATE TRIGGER TRG_AUD_DWH_DIM_CLIENTE_AI AFTER INSERT ON `dwh_dim_cliente` FOR EACH ROW INSERT INTO LOG_AUDITORIA (id_Log, id_Usuario, log_FechaHora, log_TablaAfectada, log_Accion, log_IP, log_ValorAnterior, log_ValorNuevo) VALUES (LEFT(REPLACE(UUID(), '-', ''), 15), NULLIF(@auditoria_usuario, ''), NOW(), 'DWH_DIM_CLIENTE', 'INSERT', NULLIF(@auditoria_ip, ''), NULL, JSON_OBJECT('sk_cliente', NEW.`sk_cliente`, 'id_cliente_oltp', NEW.`id_cliente_oltp`, 'nombre_cliente', NEW.`nombre_cliente`, 'tipo_cliente', NEW.`tipo_cliente`, 'ruc_ced', NEW.`ruc_ced`, 'ciudad', NEW.`ciudad`, 'provincia', NEW.`provincia`, 'region', NEW.`region`))//
